 *         .waterColor("#3f76e4").waterFogColor("#050533")
 *         .ambientSound(SoundEvent.AMBIENT_CAVE))
 *       .spawn(SpawnCategory.CREATURE, EntityType.SHEEP, { weight: 12, min: 4, max: 4 })
